const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Europe/Kyiv' });
const journal = $input.all().map(i => i.json)
  .filter(r => r.run_date && String(r.run_date) < today);

const lastDate = journal.map(r => String(r.run_date)).sort().pop();
const everSeen = {}, lastDay = {};
for (const r of journal) {
  const id = String(r.entity_id);
  (everSeen[r.rule] ??= new Set()).add(id);
  if (String(r.run_date) === lastDate) (lastDay[r.rule] ??= new Set()).add(id);
}

const parse = s => (s ? String(s).split(',') : []);
const rules = [
  { rule: 'courier', title: 'Couriers',       ids: parse($('Couriers').first().json.ids) },
  { rule: 'ring',    title: 'Ring devices',   ids: parse($('Rings').first().json.ids) },
  { rule: 'abuser',  title: 'Refund abusers', ids: parse($('Abusers').first().json.ids) },
];

const baseline = journal.length === 0;
const lines = [];
let total = 0, changes = 0;
for (const r of rules) {
  const seen = everSeen[r.rule] || new Set();
  const prev = lastDay[r.rule] || new Set();
  const todaySet = new Set(r.ids);
  const fresh = r.ids.filter(id => !seen.has(id));
  const dropped = [...prev].filter(id => !todaySet.has(id));
  total += r.ids.length;
  changes += fresh.length + dropped.length;
  lines.push(`${r.title}: 🆕 ${fresh.length} · 🔁 ${r.ids.length - fresh.length} · ✅ dropped ${dropped.length}`);
  if (!baseline && fresh.length) lines.push('  new: ' + fresh.slice(0, 10).join(', '));
  if (dropped.length) lines.push('  dropped: ' + dropped.slice(0, 10).join(', '));
}

const header = baseline ? '🔎 Daily antifraud digest (baseline run, journal is empty)'
  : changes ? '🔎 Daily antifraud digest: changes found'
  : '🔎 Daily antifraud digest: no changes';
return [{ json: { message: header + '\n\n' + lines.join('\n'), total } }];
